import{_ as e,o as i,c as l,ak as s}from"./chunks/framework.DJ-92fJv.js";const p=JSON.parse('{"title":"⌨️ 解锁键盘鼠标锁","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"features/unlock-keyboard.md","filePath":"features/unlock-keyboard.md"}'),t={name:"features/unlock-keyboard.md"};function h(r,a,n,d,o,c){return i(),l("div",null,[...a[0]||(a[0]=[s('<h1 id="⌨️-解锁键盘鼠标锁" tabindex="-1">⌨️ 解锁键盘鼠标锁 <a class="header-anchor" href="#⌨️-解锁键盘鼠标锁" aria-label="Permalink to “⌨️ 解锁键盘鼠标锁”">​</a></h1><p><strong>主菜单选项：<code>4</code></strong></p><p>当键盘和鼠标被<strong>锁定</strong>，无法进行任何输入操作时，使用此功能恢复输入设备的正常使用。</p><h2 id="执行流程" tabindex="-1">执行流程 <a class="header-anchor" href="#执行流程" aria-label="Permalink to “执行流程”">​</a></h2><h3 id="步骤-1-终止键鼠控制进程并删除驱动文件" tabindex="-1">步骤 1：终止键鼠控制进程并删除驱动文件 <a class="header-anchor" href="#步骤-1-终止键鼠控制进程并删除驱动文件" aria-label="Permalink to “步骤 1：终止键鼠控制进程并删除驱动文件”">​</a></h3><ul><li>终止 <code>BlackSlient.exe</code> — 黑屏/键鼠锁定进程</li><li>终止 <code>MultiClient.exe</code> — 学生端主进程</li><li>自动检测噢易安装路径</li><li>删除键盘锁驱动文件： <ul><li><code>LockKeyboard.dll</code> — 键盘锁定动态库</li><li><code>LoadDriver.exe</code> — 驱动加载程序</li><li><code>BlackSlient.exe</code> — 黑屏锁定程序</li><li><code>LISSNetInfoSniffer.exe</code>（位于 x86 子目录）</li></ul></li></ul><h3 id="步骤-2-删除网络限制相关文件" tabindex="-1">步骤 2：删除网络限制相关文件 <a class="header-anchor" href="#步骤-2-删除网络限制相关文件" aria-label="Permalink to “步骤 2：删除网络限制相关文件”">​</a></h3><p>在噢易安装目录中自动清理 <code>OeNetLimit</code> 文件：</p><ul><li><code>OeNetLimitSetup.exe</code> — 网络限制安装程序</li><li><code>OeNetLimit.sys</code> — 网络限制驱动文件</li><li><code>OeNetLimit.inf</code> — 网络限制配置信息</li></ul><h2 id="手动执行命令" tabindex="-1">手动执行命令 <a class="header-anchor" href="#手动执行命令" aria-label="Permalink to “手动执行命令”">​</a></h2><p>在 CMD（管理员身份）中依次执行以下命令：</p><h3 id="命令-1-终止黑屏-键鼠锁定进程" tabindex="-1">命令 1：终止黑屏/键鼠锁定进程 <a class="header-anchor" href="#命令-1-终止黑屏-键鼠锁定进程" aria-label="Permalink to “命令 1：终止黑屏/键鼠锁定进程”">​</a></h3><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">taskkill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f /im BlackSlient.exe</span></span></code></pre></div><p>强制终止黑屏和键鼠锁定进程，恢复屏幕显示和输入设备。</p><h3 id="命令-2-终止学生端主进程" tabindex="-1">命令 2：终止学生端主进程 <a class="header-anchor" href="#命令-2-终止学生端主进程" aria-label="Permalink to “命令 2：终止学生端主进程”">​</a></h3><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">taskkill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f /im MultiClient.exe</span></span></code></pre></div><p>强制终止学生端主进程 <code>MultiClient.exe</code>，停止其管控逻辑。</p><h3 id="命令-3-删除键盘锁驱动文件" tabindex="-1">命令 3：删除键盘锁驱动文件 <a class="header-anchor" href="#命令-3-删除键盘锁驱动文件" aria-label="Permalink to “命令 3：删除键盘锁驱动文件”">​</a></h3><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">del</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /F /Q </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:\\Program Files (x86)\\Os-Easy\\os-easy multicast teaching system\\LockKeyboard.dll&quot;</span></span></code></pre></div><p>删除键盘锁定动态库文件，彻底解除键盘锁定。如果噢易安装在 <code>C:\\Program Files</code> 目录，请相应调整路径。</p><h3 id="命令-4-删除驱动加载程序" tabindex="-1">命令 4：删除驱动加载程序 <a class="header-anchor" href="#命令-4-删除驱动加载程序" aria-label="Permalink to “命令 4：删除驱动加载程序”">​</a></h3><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">del</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /F /Q </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:\\Program Files (x86)\\Os-Easy\\os-easy multicast teaching system\\LoadDriver.exe&quot;</span></span></code></pre></div><p>删除驱动加载程序，防止键盘锁驱动被重新加载。</p><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to “使用场景”">​</a></h2><ul><li>✅ 键盘被锁定，<strong>无法打字</strong>或按任何键</li><li>✅ 鼠标被锁定，<strong>光标无法移动</strong>或点击无效</li><li>✅ 全键盘 / 全鼠标被老师远程禁用</li><li>✅ 同时存在黑屏状态（此功能同时处理 <code>BlackSlient.exe</code>）</li></ul><h2 id="效果说明" tabindex="-1">效果说明 <a class="header-anchor" href="#效果说明" aria-label="Permalink to “效果说明”">​</a></h2><p>执行后：</p><ul><li>键盘恢复正常，可以输入文字</li><li>鼠标恢复正常，可以自由移动和点击</li><li>黑屏状态解除（如果存在）</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><h3 id="q-终止后又锁了怎么办" tabindex="-1">Q：终止后又锁了怎么办？ <a class="header-anchor" href="#q-终止后又锁了怎么办" aria-label="Permalink to “Q：终止后又锁了怎么办？”">​</a></h3><p>学生端可能自动重启了相关进程。可以再次执行终止命令，或使用 <strong>持续监控模式</strong>。</p><h3 id="q-删除驱动文件提示权限不足" tabindex="-1">Q：删除驱动文件提示权限不足？ <a class="header-anchor" href="#q-删除驱动文件提示权限不足" aria-label="Permalink to “Q：删除驱动文件提示权限不足？”">​</a></h3><p>确保已以管理员身份运行 CMD。如果仍然提示，可以先尝试在安全模式下删除。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">注意</p><p>部分机房环境在重启学生端后键盘锁驱动可能被重新加载。如果再次遇到键盘鼠标锁，重新运行此功能即可。</p></div>',35)])])}const b=e(t,[["render",h]]);export{p as __pageData,b as default};
